# 표시 계층 한국어 번역: DB/OCR 키로 쓰이는 중국어 게임 명칭을 위젯에 표시할 때만 한국어로 바꾼다.
"""Display-layer Korean translation for DB-derived game terms.

Internal identifiers (character names, attribute names, suit names, sentinel values)
must stay Chinese because they are matched against OCR output, static-DB rows and
persisted user data.  This module patches PySide6 widget text setters so that the
*rendered* text is Korean while ``text()``-style read-backs still return the
original value.  Long static-DB descriptions are translated at the DAO boundary
through an exact-match dictionary (``src.i18n_desc``).
"""

from __future__ import annotations

import re
from typing import Any

from PySide6 import QtCore, QtGui, QtWidgets

