def _install_static_dao() -> None:
    if not DESC:
        return
    try:
        from src.storage.sqlite.static_game_data_dao import StaticGameDataDao
    except Exception:
        return
    original = StaticGameDataDao._rows

    def rows(self, sql, parameters=()):
        result = original(self, sql, parameters)
        for row in result:
            for key, value in row.items():
                if isinstance(value, str) and value in DESC:
                    row[key] = DESC[value]
        return result

    StaticGameDataDao._rows = rows


_INSTALLED = False


def install() -> None:
    """Install every display patch once."""
    global _INSTALLED
    if _INSTALLED:
        return
    _INSTALLED = True
    steps = [
        lambda: _install_text_widget(QtWidgets.QLabel, "setText", "text"),
        lambda: _install_ctor_retranslate(QtWidgets.QLabel, "setText", "text"),
        lambda: _install_text_widget(QtWidgets.QAbstractButton, "setText", "text"),
        lambda: [_install_ctor_retranslate(c, "setText", "text") for c in (QtWidgets.QPushButton, QtWidgets.QCheckBox, QtWidgets.QRadioButton, QtWidgets.QToolButton)],
        lambda: _install_text_widget(QtWidgets.QGroupBox, "setTitle", "title"),
        lambda: _install_ctor_retranslate(QtWidgets.QGroupBox, "setTitle", "title"),
        lambda: _install_item(QtWidgets.QTableWidgetItem, False),
        lambda: _install_item(QtWidgets.QListWidgetItem, False),
        lambda: _install_item(QtWidgets.QTreeWidgetItem, True),
        lambda: _install_item(QtGui.QStandardItem, False),
        _install_combo,
        _install_tabs,
        _install_simple_setters,
        _install_static_dialogs,
        _install_painter,
        _install_layout_labels,
        _install_item_tooltips,
        _install_message_box_ctor,
        lambda: _install_text_widget(QtWidgets.QLineEdit, "setText", "text"),
        _install_search_combo,
        _install_search_warehouse,
        _install_search_catalog,
        _install_models,
        _install_static_dao,
    ]
    for step in steps:
        try:
            step()
        except Exception as exc:  # pragma: no cover - never break startup
            print(f"[i18n_display] patch step failed: {exc}")
